const terpenes=[["Myrcene","Often associated with body relaxation and nighttime-style directions."],["Limonene","Often associated with bright citrus aroma and uplifted directions."],["Pinene","Often associated with pine aroma and clearer daytime directions."],["Caryophyllene","Often associated with peppery aroma and calming body comfort."],["Linalool","Often associated with floral aroma and calming relaxation."],["Terpinolene","Often associated with fresh herbal aroma and creative daytime directions."]];
let currentFilter="All",deferredPrompt=null;
function $(id){return document.getElementById(id)}function safeName(n){return String(n).replace(/'/g,"\\'")}function showToast(m){const t=$("toast");t.textContent=m;t.style.display="block";setTimeout(()=>t.style.display="none",1700)}
function showPage(id){document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));$(id).classList.add("active");document.querySelectorAll(".nav-btn").forEach(b=>b.classList.remove("active"));let i=["home","search","recommend","saved","learn"].indexOf(id);if(i>=0)document.querySelectorAll(".nav-btn")[i].classList.add("active");window.scrollTo({top:0,behavior:"smooth"});if(id==="saved")renderSaved();if(id==="home")renderRecentHome()}
function visualClass(s){return "visual-"+(s.category==="Body Comfort"?"Body":s.category)}function cardHTML(s){return `<article class="strain-card" onclick="openModal('${safeName(s.name)}')"><div class="card-hero ${visualClass(s)}"><div class="card-emoji">${s.emoji}</div></div><span class="eyebrow">${s.type}</span><h3>${s.name}</h3><p>${s.insight}</p><div class="tags">${s.tags.map(t=>`<span class="tag">${t}</span>`).join("")}</div></article>`}
function renderFeatured(){$("featuredGrid").innerHTML=strains.slice(0,18).map(cardHTML).join("")}function renderFilters(){$("filterRow").innerHTML=filters.map(f=>`<button class="filter-chip ${f===currentFilter?'active':''}" onclick="setFilter('${f}')">${f}</button>`).join("")}function setFilter(f){currentFilter=f;renderFilters();renderSearch()}
function searchableText(s){return [s.name,s.type,s.category,s.tags.join(" "),s.goals.join(" "),s.terpenes.join(" "),s.thc,s.cbd,s.time,s.flavor,s.insight].join(" ").toLowerCase()}
function renderSearch(){const q=$("searchInput").value.toLowerCase().trim();const filtered=strains.filter(s=>{const text=searchableText(s);return(!q||text.includes(q))&&(currentFilter==="All"||text.includes(currentFilter.toLowerCase()))});$("strainGrid").innerHTML=filtered.length?filtered.map(cardHTML).join(""):`<div class="panel"><h3>No matches yet</h3><p>Try another strain, goal, terpene, or feeling.</p></div>`}
function addRecent(name){let r=JSON.parse(localStorage.getItem("srRecent")||"[]");r=r.filter(x=>x!==name);r.unshift(name);r=r.slice(0,8);localStorage.setItem("srRecent",JSON.stringify(r));renderRecentHome();updateStats()}
function renderRecentHome(){const r=JSON.parse(localStorage.getItem("srRecent")||"[]");$("recentHome").innerHTML=r.length?r.map(n=>`<div class="mini-item" onclick="openModal('${safeName(n)}')">${n}</div>`).join(""):`<div class="empty-state">No recently viewed strains yet. Open a strain profile to start.</div>`}
function openModal(name){const s=strains.find(x=>x.name===name);if(!s)return;addRecent(name);const sim=strains.filter(x=>x.name!==s.name&&(x.category===s.category||x.goals.some(g=>s.goals.includes(g)))).slice(0,4);$("modalBody").innerHTML=`<div class="modal-head"><div class="modal-emoji">${s.emoji}</div><div><span class="eyebrow">Strain Profile</span><h2>${s.name}</h2><p>${s.type}</p></div></div><div class="tags">${s.tags.map(t=>`<span class="tag">${t}</span>`).join("")}</div><div class="panel"><h3>Match Score: ${s.score}%</h3><div class="score-bar"><div class="score-fill" style="width:${s.score}%"></div></div><p>${s.insight}</p></div><div class="panel"><h3>AI-style Match Explanation</h3><p>This direction may align with ${s.goals.join(", ").toLowerCase()} because it is commonly described as ${s.tags.join(", ").toLowerCase()} with ${s.terpenes.join(", ")} terpenes. Educational only.</p></div><div class="panel"><h3>THC / CBD Direction</h3><p><strong>THC:</strong> ${s.thc}</p><p><strong>CBD:</strong> ${s.cbd}</p><p><strong>Best time:</strong> ${s.time}</p><p><strong>Flavor / aroma:</strong> ${s.flavor}</p></div><div class="panel"><h3>Terpene Direction</h3><div class="tags">${s.terpenes.map(t=>`<span class="tag">${t}</span>`).join("")}</div></div><div class="panel"><h3>May align with</h3><div class="tags">${s.goals.map(t=>`<span class="tag">${t}</span>`).join("")}</div></div><div class="panel"><h3>Use caution if</h3><div class="tags">${s.caution.map(t=>`<span class="tag">${t}</span>`).join("")}</div></div><div class="panel"><h3>Similar directions</h3><div class="tags">${sim.map(t=>`<span class="tag" onclick="openModal('${safeName(t.name)}')">${t.name}</span>`).join("")}</div></div><button onclick="saveFavorite('${safeName(s.name)}')">Save ${s.name}</button><button class="ghost" onclick="prefillJournal('${safeName(s.name)}')">Add Journal Note</button><button class="ghost" onclick="shareStrain('${safeName(s.name)}')">Share Direction</button>`;$("strainModal").classList.remove("hidden");document.body.classList.add("modal-open")}
function closeModal(){$("strainModal").classList.add("hidden");document.body.classList.remove("modal-open")}$("strainModal").addEventListener("click",e=>{if(e.target.id==="strainModal")closeModal()});
function saveFavorite(name){let s=JSON.parse(localStorage.getItem("srSaved")||"[]");if(!s.includes(name))s.unshift(name);localStorage.setItem("srSaved",JSON.stringify(s.slice(0,50)));renderSaved();updateStats();showToast("Saved "+name)}function removeFavorite(name){let s=JSON.parse(localStorage.getItem("srSaved")||"[]").filter(x=>x!==name);localStorage.setItem("srSaved",JSON.stringify(s));renderSaved();updateStats()}function clearSaved(){localStorage.removeItem("srSaved");renderSaved();updateStats()}
function renderSaved(){const s=JSON.parse(localStorage.getItem("srSaved")||"[]");$("savedList").innerHTML=s.length?s.map(n=>`<div class="mini-item"><span onclick="openModal('${safeName(n)}')">${n}</span> <button class="small-btn ghost" onclick="removeFavorite('${safeName(n)}')">Remove</button></div>`).join(""):`<div class="empty-state"><strong>No favorites yet.</strong><br>Search or match a strain, then tap save.</div>`;renderJournal();updateStats()}
function loadJournalSelect(){$("journalStrain").innerHTML=`<option value="">Select strain</option>`+strains.map(s=>`<option>${s.name}</option>`).join("")}function prefillJournal(name){closeModal();showPage("saved");$("journalStrain").value=name;$("journalNote").focus()}
function saveJournal(){const strain=$("journalStrain").value,mood=$("journalMood").value,note=$("journalNote").value.trim();if(!strain){showToast("Select a strain first");return}let j=JSON.parse(localStorage.getItem("srJournal")||"[]");j.unshift({strain,mood,note,date:new Date().toLocaleDateString()});localStorage.setItem("srJournal",JSON.stringify(j.slice(0,80)));$("journalMood").value="";$("journalNote").value="";renderJournal();updateStats();showToast("Journal saved")}
function deleteJournal(i){let j=JSON.parse(localStorage.getItem("srJournal")||"[]");j.splice(i,1);localStorage.setItem("srJournal",JSON.stringify(j));renderJournal();updateStats()}function clearJournal(){localStorage.removeItem("srJournal");renderJournal();updateStats()}
function renderJournal(){const j=JSON.parse(localStorage.getItem("srJournal")||"[]");$("journalList").innerHTML=j.length?j.map((x,i)=>`<div class="mini-item"><strong>${x.strain}</strong><br>${x.date} · ${x.mood||"No mood selected"}<br>${x.note||"No notes added."}<br><button class="small-btn ghost" onclick="deleteJournal(${i})">Delete</button></div>`).join(""):`<div class="empty-state">No journal entries yet.</div>`;renderJournalChart(j)}
function renderJournalChart(j){if(!j.length){$("journalChart").innerHTML="";return}const c={};j.forEach(x=>{if(x.mood)c[x.mood]=(c[x.mood]||0)+1});const max=Math.max(...Object.values(c),1);$("journalChart").innerHTML=`<h3>Mood Tracker</h3>`+Object.keys(c).map(k=>`<div class="chart-line"><div class="chart-label"><span>${k}</span><span>${c[k]}</span></div><div class="chart-bar"><div class="chart-fill" style="width:${(c[k]/max)*100}%"></div></div></div>`).join("")}
function runMatcher(){const goal=$("goalSelect").value,sens=$("sensitivitySelect").value,time=$("timeSelect").value,low=$("lowAnxietyToggle").checked;let r=strains.filter(s=>!goal||s.goals.includes(goal)||s.tags.includes(goal)||s.category===goal||s.insight.includes(goal));if(sens==="low"||low)r=r.filter(s=>s.thc.toLowerCase().includes("low")||s.cbd.toLowerCase().includes("high")||s.tags.includes("CBD-forward"));if(time)r=r.filter(s=>s.time.includes(time)||s.tags.includes(time));if(!r.length)r=strains.filter(s=>s.category==="CBD").slice(0,8);r=r.sort((a,b)=>b.score-a.score).slice(0,12);$("matchExplain").classList.remove("hidden");$("matchExplain").innerHTML=`<h3>Why this match?</h3><p>These directions were selected using your goal, THC sensitivity, preferred time, terpene direction, and Low Anxiety Mode. Start low, ask for lab-tested options, follow local laws, and avoid driving while impaired.</p>`;$("matchResults").innerHTML=r.map(cardHTML).join("");showToast("Directions matched")}
function shareStrain(name){const text=`StrainRelief wellness direction: ${name}. Educational only. Follow local laws.`;if(navigator.share)navigator.share({title:"StrainRelief",text,url:location.href});else{navigator.clipboard.writeText(text+" "+location.href);showToast("Copied share text")}}
function renderEducation(){$("onboardingSlides").innerHTML=`<h3>Quick Start</h3><div class="mini-list"><div class="mini-item"><strong>1. Search</strong><br>Find strain directions by name, effect, or terpene.</div><div class="mini-item"><strong>2. Match</strong><br>Use your goal and sensitivity.</div><div class="mini-item"><strong>3. Save + Journal</strong><br>Track what you explored and how it felt.</div></div>`;$("terpeneExplorer").innerHTML=`<h3>Terpene Explorer</h3><div class="mini-list">${terpenes.map(t=>`<div class="mini-item"><strong>${t[0]}</strong><br>${t[1]}</div>`).join("")}</div>`;$("locatorBox").innerHTML=`<h3>Dispensary Prep</h3><p>Locator coming later. For now, use this checklist when shopping legally.</p><button onclick="copyChecklist()">Copy Checklist</button>`;$("termsBox").innerHTML=`<h3>Privacy + Terms</h3><p>This version stores favorites, recent views, and journal entries locally on your device. No account system is active yet. StrainRelief is educational only.</p>`;$("learnGrid").innerHTML=education.map(e=>`<div class="education-card"><h3>${e.title}</h3><p>${e.body}</p></div>`).join("")}
function copyChecklist(){navigator.clipboard.writeText("Ask for lab-tested products, THC/CBD percentages, terpene profile, serving size, onset time, and lower-risk beginner-friendly options. Follow local laws. Do not drive while impaired.");showToast("Checklist copied")}
function dailyTip(){const p=strains[new Date().getDate()%strains.length];$("dailyTitle").textContent=p.name;$("dailyText").textContent=p.insight+" Educational only — start low and follow local laws."}function updateStats(){$("strainCount").textContent=strains.length;$("savedCount").textContent=JSON.parse(localStorage.getItem("srSaved")||"[]").length;$("journalCount").textContent=JSON.parse(localStorage.getItem("srJournal")||"[]").length}
window.addEventListener("load",()=>{setTimeout(()=>{const s=$("splash");if(s){s.style.opacity="0";setTimeout(()=>s.remove(),450)}},550)});window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredPrompt=e;if(localStorage.getItem("srInstallDismissed")!=="yes")$("installBanner").classList.remove("hidden")});function dismissInstall(){localStorage.setItem("srInstallDismissed","yes");$("installBanner").classList.add("hidden")}$("installBtn").addEventListener("click",async()=>{if(!deferredPrompt){showToast("Use browser menu to install");return}deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$("installBanner").classList.add("hidden")});
if("serviceWorker" in navigator){navigator.serviceWorker.register("service-worker.js").catch(()=>{})}$("searchInput").addEventListener("input",renderSearch);dailyTip();renderFeatured();renderFilters();renderSearch();loadJournalSelect();renderSaved();renderRecentHome();renderEducation();updateStats();
